CREATE OR REPLACE FUNCTION security.admin_evidence_page_default_fast(p_args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'security', 'pipeline', 'workflow', 'ref', 'auth', 'storage'
AS $function$
declare v_rank integer:=0; v_limit integer:=least(greatest(coalesce((p_args->>'limit')::integer,50),1),200); v_offset integer:=greatest(coalesce((p_args->>'offset')::integer,0),0); v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 select security.current_role_rank() into v_rank;
 if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
 if nullif(trim(coalesce(p_args->>'query','')),'') is not null or nullif(trim(coalesce(p_args->>'country','')),'') is not null or nullif(trim(coalesce(p_args->>'source_id','')),'') is not null or nullif(trim(coalesce(p_args->>'layer','')),'') is not null or nullif(trim(coalesce(p_args->>'entity_type','')),'') is not null or nullif(trim(coalesce(p_args->>'entity_id','')),'') is not null or nullif(trim(coalesce(p_args->>'provider_id','')),'') is not null or nullif(trim(coalesce(p_args->>'job_id','')),'') is not null or nullif(trim(coalesce(p_args->>'evidence_type','')),'') is not null or nullif(trim(coalesce(p_args->>'mime','')),'') is not null or nullif(trim(coalesce(p_args->>'hash','')),'') is not null or nullif(trim(coalesce(p_args->>'job_status','')),'') is not null or nullif(trim(coalesce(p_args->>'status','')),'') is not null or nullif(trim(coalesce(p_args->>'extraction_state','')),'') is not null or nullif(trim(coalesce(p_args->>'freshness','')),'') is not null or nullif(trim(coalesce(p_args->>'verified_from','')),'') is not null or nullif(trim(coalesce(p_args->>'verified_to','')),'') is not null or p_args ? 'unresolved_conflicts' or lower(coalesce(p_args->>'sort','captured')) <> 'captured' or lower(coalesce(p_args->>'direction','desc')) <> 'desc' then return security.admin_evidence_page(p_args); end if;
 with page_ids as materialized (select e.id,e.captured_at from pipeline.evidence_artifacts e order by e.captured_at desc nulls last,e.id limit v_limit offset v_offset),
 page_rows as materialized (
  select e.id,e.source_id,e.job_id,e.evidence_type,e.source_url,e.content_hash,e.mime_type,e.captured_at,e.valid_from,e.valid_to,e.supersedes_evidence_id,e.storage_path,e.metadata,s.label source_label,s.source_type,s.status source_status,s.url authority_url,co.iso_alpha2 country_code,j.job_type,j.domain job_domain,j.status job_status,security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type) layer_code,(lower(coalesce(e.metadata->>'freshness_state',''))='stale' or lower(coalesce(e.metadata->>'stale','false'))='true') explicit_stale,coalesce(ls.observation_count,0) observation_count,coalesce(ls.source_null_count,0) source_null_count,coalesce(ls.rejected_count,0) rejected_count,
  exists(select 1 from workflow.review_queue rq join pipeline.claims cl on cl.id=rq.candidate_claim_id where cl.evidence_id=e.id and lower(coalesce(rq.status,'open')) not in ('closed','resolved','accepted','rejected')) unresolved_conflict,
  exists(select 1 from pipeline.evidence_artifacts su where su.supersedes_evidence_id=e.id) is_superseded,
  exists(select 1 from storage.objects o where o.bucket_id='evidence' and o.name=e.storage_path) storage_available
  from page_ids p join pipeline.evidence_artifacts e on e.id=p.id left join pipeline.sources s on s.id=e.source_id left join ref.countries co on co.id=s.country_id left join pipeline.jobs j on j.id=e.job_id left join pipeline.evidence_lineage_stats ls on ls.evidence_id=e.id
 ), classified as (
  select r.*,case when r.unresolved_conflict then 'conflict' when r.rejected_count>0 then 'rejected' when r.observation_count=0 then 'missing_extraction' when r.source_null_count>0 then 'source_null' when r.explicit_stale then 'stale' when (r.valid_to is not null and r.valid_to<now()) or r.is_superseded then 'superseded' else 'current' end operational_status from page_rows r
 )
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'country_code',x.country_code,'source_id',x.source_id,'source_label',x.source_label,'source_type',x.source_type,'source_status',x.source_status,'authority_url',x.authority_url,'layer',x.layer_code,'job_id',x.job_id,'job_type',x.job_type,'job_domain',x.job_domain,'job_status',x.job_status,'evidence_type',x.evidence_type,'mime_type',x.mime_type,'captured_at',x.captured_at,'valid_from',x.valid_from,'valid_to',x.valid_to,'content_hash',x.content_hash,'extraction_state',case when x.rejected_count>0 and x.observation_count=0 then 'rejected' when x.observation_count>0 then 'extracted' else 'missing_extraction' end,'observation_count',x.observation_count,'has_source_null',x.source_null_count>0,'status',x.operational_status,'freshness_state',case when x.explicit_stale then 'stale' when x.valid_to is not null and x.valid_to<now() then 'expired' when x.valid_to is not null then 'current' else 'no_policy' end,'unresolved_conflict',x.unresolved_conflict,'history_state',case when x.is_superseded then 'superseded' when x.supersedes_evidence_id is not null then 'superseding_snapshot' else 'current_or_unversioned' end,'storage_available',x.storage_available) order by x.captured_at desc nulls last,x.id) from classified x),'[]'::jsonb),'total',(select count(*) from pipeline.evidence_artifacts),'limit',v_limit,'offset',v_offset) into v_result;
 return v_result;
end $function$
